mapper.select:
SELECT  FROM ast_device d
WHERE d.tenant_id=#{query.tenantId} AND d.deleted=0 AND d.source_system='DPPMS' AND d.id > #{query.afterId}
ORDER BY d.id LIMIT #{query.limit} FOR UPDATE

SELECT b.source_key,b.target_id project_id FROM int_base_sync_binding b JOIN int_base_sync_task t
  ON t.id=b.task_id AND t.tenant_id=b.tenant_id AND t.deleted=0 AND t.task_code='BASE_P16' AND t.connection_id=#{query.connectionId}
WHERE b.tenant_id=#{query.tenantId} AND b.deleted=0 AND b.object_key='PROJECT_ALIAS'

  AND b.source_key IN #{key}
AND 1=0

mapper.update:
UPDATE ast_device_project_relationship r JOIN (
  VALUES ROW(#{change.device.sn},#{change.device.projectAssignmentVersion})
) incoming(sn,assignment_version) ON r.device_sn=incoming.sn COLLATE utf8mb4_unicode_ci
SET r.effective_to=#{context.startedAt},r.assignment_version=incoming.assignment_version+1,
  r.version=r.version+1,r.updater=#{context.actorId},r.update_time=#{context.startedAt}
WHERE r.tenant_id=#{context.tenantId} AND r.deleted=0 AND r.relationship_type='DIRECT' AND r.source_system='BASE_SYNC'
  AND r.effective_to IS NULL AND r.assignment_version=incoming.assignment_version AND r.effective_from < #{context.startedAt}

UPDATE int_base_sync_binding b JOIN (
  VALUES ROW(#{change.binding.id},#{change.device.id},#{change.binding.fingerprint},#{change.nextFingerprint})
) incoming(id,device_id,previous_fingerprint,fingerprint) ON incoming.id=b.id AND incoming.device_id=b.target_id
SET b.fingerprint=incoming.fingerprint,b.updater=#{context.actorId}
WHERE b.tenant_id=#{context.tenantId} AND b.deleted=0 AND b.object_key='DEVICE_BASE'
  AND b.fingerprint=incoming.previous_fingerprint COLLATE utf8mb4_unicode_ci

mapper.delete:
DELETE FROM ast_device_project_ancestor WHERE tenant_id=#{context.tenantId}

  AND device_sn IN #{projection.sn}
AND 1=0
